@charset "UTF-8";
.ImageError-module__imageError {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  width: 100%;
  background-color: var(--color-secondary-container);
  color: var(--color-on-surface);
  position: relative;
}
.BrandTooltip-module__container {
  display: inline-flex;
  position: relative;
  anchor-name: var(--anchor-name);
}
.BrandTooltip-module__tooltip {
  padding: var(--dimension-400) var(--margin-450);
  color: var(--color-on-surface);
  background: var(--appearance-color-bg-primary);
  border-radius: var(--chat-view-bubble-radius);
  z-index: 99999;
  position: fixed;
  position-anchor: var(--anchor-name);
  margin: var(--dimension-300);
  box-shadow: var(--shadow-large-15);
}
.BrandTooltip-module__tooltip.BrandTooltip-module__disableHover {
  pointer-events: none;
}
.BrandTooltip-module__tooltip.BrandTooltip-module__top,
.BrandTooltip-module__tooltip.BrandTooltip-module__bottom {
  position-try: flip-block;
}
.BrandTooltip-module__tooltip.BrandTooltip-module__top {
  bottom: anchor(top);
  justify-self: anchor-center;
}
.BrandTooltip-module__tooltip.BrandTooltip-module__bottom {
  top: anchor(bottom);
  justify-self: anchor-center;
}
.BrandTooltip-module__tooltip.BrandTooltip-module__left,
.BrandTooltip-module__tooltip.BrandTooltip-module__right {
  position-try: flip-inline;
}
.BrandTooltip-module__tooltip.BrandTooltip-module__left {
  position-area: center left;
}
.BrandTooltip-module__tooltip.BrandTooltip-module__right {
  position-area: center right;
}
.BrandTooltip-module__content,
.BrandTooltip-module__hotkey span {
  font-weight: 500;
  font-size: var(--semantic-typo-size-body-sm);
  line-height: var(--semantic-typo-line-height-body-md);
  letter-spacing: var(--semantic-typo-letter-spacing-body-sm);
}
.BrandTooltip-module__hotkey {
  display: inline-flex;
  gap: var(--dimension-200);
  margin-left: var(--dimension-400);
}
.BrandTooltip-module__hotkey span {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  aspect-ratio: 1/1;
  height: 1.5em;
  background: var(--color-secondary-container);
  padding: var(--dimension-100);
  border-radius: var(--radius-4);
}
.DefaultAvatar-module__wrapper {
  width: 100%;
  height: 100%;
  user-select: none;
}
.DefaultAvatar-module__circle {
  container-type: size;
  border-radius: 100%;
  font-family: Knicknack;
  color: #fff;
  text-align: center;
  max-width: 100%;
  max-height: 100%;
  aspect-ratio: 1;
  margin: auto;
  display: grid;
  place-items: center;
}
.DefaultAvatar-module__text {
  font-weight: 500;
  font-size: 50cqw;
  display: block;
  line-height: 1em;
  letter-spacing: var(--letter-spacing);
  margin-right: calc(var(--letter-spacing) * -1);
}
.UnknownAvatar-module__container {
  width: 100%;
  height: 100%;
  display: block;
}
.UnknownAvatar-module__background {
  fill: var(--color-backing-shade);
}
.UnknownAvatar-module__foreground {
  fill: var(--appearance-color-text-on-main);
}
.BrandNetworkIcon-module__brandNetworkIcon {
  color: var(--palette-base-white);
  border-radius: 35%;
}
.BrandNetworkIcon-module__brandNetworkIcon svg {
  z-index: 1;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.BrandNetworkIcon-module__brandNetworkIcon.BrandNetworkIcon-module__isBadge {
  color: currentColor;
}
.BrandNetworkIcon-module__brandBackground.BrandNetworkIcon-module__isBadge {
  background: unset !important;
  background-color: var(--color-backing-shade) !important;
}
.PlatformIcon-module__sfSymbolIcon {
  display: inline-block;
  -webkit-mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-size: contain;
  mask-repeat: no-repeat;
  mask-position: center;
  background-color: currentColor;
}
.PlatformIcon-module__materialIcon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.PlatformIcon-module__materialIcon > svg {
  flex-shrink: 0;
}
.BrandLink-module__link {
  cursor: default;
  color: var(--color-primary);
  font-weight: 400;
  font-size: var(--semantic-typo-size-body-md);
  line-height: var(--semantic-typo-line-height-body-md);
  letter-spacing: var(--semantic-typo-letter-spacing-body-md);
  text-underline-offset: var(--dimension-100);
}
.BrandLink-module__link.BrandLink-module__underline {
  text-decoration: underline;
}
.BrandLink-module__link:hover {
  filter: brightness(1.25);
}
.BrandLink-module__link:active {
  filter: brightness(0.75);
}
.Toasts-module__container {
  pointer-events: auto;
  display: flex;
  gap: var(--dimension-400);
  padding: var(--dimension-400);
  max-width: max-content;
  min-height: 2rem;
  background: var(--appearance-color-bg-primary);
  box-shadow: var(--shadow-medium-15);
  border-radius: var(--radius-10);
  font-weight: 400;
  font-size: var(--semantic-typo-size-body-sm);
  line-height: var(--semantic-typo-line-height-body-sm);
  letter-spacing: var(--semantic-typo-letter-spacing-body-sm);
  color: var(--color-on-surface);
}
.Toasts-module__container .Toasts-module__content {
  white-space: pre-wrap;
  word-break: break-word;
  pointer-events: auto;
  flex-wrap: wrap;
  max-height: 30vh;
  overflow-y: auto;
}
.Toasts-module__container.Toasts-module__error {
  background: var(--color-on-error-container);
  color: var(--palette-base-white);
}
.Toasts-module__container.Toasts-module__brandIcon .Toasts-module__icon {
  margin: 0;
}
.Toasts-module__container.Toasts-module__brandIcon {
  align-items: center;
}
.Toasts-module__container.Toasts-module__brandIcon .Toasts-module__close,
.Toasts-module__container.Toasts-module__centeredClose .Toasts-module__close {
  align-self: center;
}
.Toasts-module__container.Toasts-module__fullWidth {
  max-width: unset;
  width: 100%;
  justify-content: center;
}
.Toasts-module__container.Toasts-module__fullWidth .Toasts-module__content {
  flex: 1;
}
.Toasts-module__container.Toasts-module__fullWidth.Toasts-module__neutral
  .Toasts-module__content {
  text-align: center;
}
.Toasts-module__icon {
  align-self: center;
}
.Toasts-module__icon,
.Toasts-module__close {
  flex-shrink: 0;
  margin: calc(-1 * var(--dimension-400));
  height: 2rem;
  width: 2rem;
  display: grid;
  place-items: center;
}
.Toasts-module__close {
  align-self: flex-start;
}
.Toasts-module__toastButtons {
  margin-top: var(--dimension-800);
}
.Toasts-module__toastButtons button {
  font-weight: 600;
  font-size: var(--semantic-typo-size-body-sm);
  line-height: var(--semantic-typo-line-height-body-sm);
  letter-spacing: var(--semantic-typo-letter-spacing-body-sm);
  line-height: var(--semantic-typo-line-height-body-md);
}
.Toasts-module__toastButtons button.Toasts-module__standout {
  color: var(--color-primary);
}
.Toasts-module__rightButton {
  font-weight: 600;
  font-size: var(--semantic-typo-size-body-sm);
  line-height: var(--semantic-typo-line-height-body-sm);
  letter-spacing: var(--semantic-typo-letter-spacing-body-sm);
  color: var(--color-primary);
}
.GroupAvatar-module__wrapper {
  position: relative;
  container-type: size;
  display: flex;
  flex-direction: row;
  border-radius: 100%;
  font-size: 24cqw;
}
.GroupAvatar-module__wrapper > .GroupAvatar-module__avatarContent:nth-child(1) {
  transform: translate(-14%, -13.5%) scale(0.48);
}
.GroupAvatar-module__wrapper > .GroupAvatar-module__avatarContent:nth-child(2) {
  transform: translate(26%, 8%) scale(0.35);
}
.GroupAvatar-module__wrapper > .GroupAvatar-module__avatarContent:nth-child(3) {
  transform: translate(-6%, 28%) scale(0.27);
}
.GroupAvatar-module__wrapper > .GroupAvatar-module__avatarContent:nth-child(4) {
  transform: translate(25%, -24%) scale(0.215);
}
.GroupAvatar-module__wrapper > .GroupAvatar-module__avatarContent:nth-child(5) {
  transform: translate(-33%, 20%) scale(0.2);
}
.GroupAvatar-module__avatarContent {
  position: absolute;
  border-radius: 100%;
  overflow: hidden;
  color: #fff;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}
.GroupAvatar-module__avatarImage {
  width: 100%;
}
.GroupAvatar-module__overflowCount {
  border-radius: 0;
  width: 30cqw;
  height: fit-content;
  font-size: 15cqw;
  text-align: center;
  letter-spacing: -0.02em;
  transform: translate(9%, 269%);
  color: var(--color-on-surface-variant);
}
.ThreadAvatar-module__wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
}
.ThreadAvatar-module__avatar {
  height: 100%;
  width: 100%;
  border-radius: 100%;
  background-color: var(--color-backing-shade);
  display: flex;
}
.ThreadPreviewTag-module__tag {
  font-weight: 600;
  font-size: var(--semantic-typo-size-label-xs);
  line-height: var(--semantic-typo-line-height-label-xs);
  letter-spacing: var(--semantic-typo-letter-spacing-label-xs);
  font-weight: 500;
  background-color: color-mix(
    in srgb,
    var(--color-on-surface) 15%,
    transparent
  );
  border-radius: 0.25rem;
  min-width: 0.875rem;
  min-height: 0.875rem;
  padding: 0 0.125rem;
  margin-right: 0.25rem;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 0;
  white-space: nowrap;
  vertical-align: top;
  margin-top: 0.0625rem;
}
.ThreadPreviewTag-module__label {
  display: flex;
  padding: 0 0.125rem;
  justify-content: center;
  align-items: center;
}
.ThreadPreviewTag-module__icon {
  flex: none;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}
.ThreadListItem-module__wrapper {
  --animation-timing: 0.1s;
  display: flex;
  align-items: center;
  position: relative;
}
.ThreadListItem-module__wrapper.ThreadListItem-module__isSelected:before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--color-background-selected);
  border-radius: var(--radius-8);
  z-index: -1;
}
.ThreadListItem-module__internal {
  width: 100%;
  padding: 10px 8px;
  color: var(--thread-children-text);
  display: flex;
  align-items: center;
  position: relative;
}
.ThreadListItem-module__checkboxWrapper {
  interpolate-size: allow-keywords;
  --out-transition: opacity 0.16s ease, width 0.12s ease 0.16s;
  --in-transition: width 0.16s ease, opacity 0.12s ease 0.16s;
  display: flex;
  flex-shrink: 0;
  width: 0;
  opacity: 0;
  transition: var(--out-transition);
}
.ThreadListItem-module__checkboxMode .ThreadListItem-module__checkboxWrapper {
  transition: var(--in-transition);
  width: fit-content;
  opacity: 1;
}
.ThreadListItem-module__indicators,
.ThreadListItem-module__proIndicators {
  --out-transition: opacity 0.08s ease 0.2s, width 0.12s ease 0.16s;
  --in-transition: width 0.16s ease, opacity 0.08s ease;
  flex-shrink: 0;
  display: flex;
  width: calc(var(--dimension-300) + 6px);
  flex-direction: column;
  gap: 4px;
  transition: var(--out-transition);
}
.ThreadListItem-module__checkboxMode .ThreadListItem-module__indicators,
.ThreadListItem-module__checkboxMode .ThreadListItem-module__proIndicators {
  transition: var(--in-transition);
  width: 0;
  opacity: 0;
}
.ThreadListItem-module__unreadIndicator,
.ThreadListItem-module__erroredIndicator {
  width: 6px;
  height: 6px;
  border-radius: 100%;
  background: var(--color-primary);
}
.ThreadListItem-module__isMuted .ThreadListItem-module__unreadIndicator {
  background: rgba(var(--color-on-surface-rgb) / 0.3);
}
.ThreadListItem-module__erroredIndicator {
  background: var(--error-color);
}
.ThreadListItem-module__avatar {
  width: var(--inbox-avatar-size);
  height: var(--inbox-avatar-size);
  flex-shrink: 0;
  position: relative;
  margin-right: var(--dimension-400);
}
.ThreadListItem-module__activityIndicator {
  position: absolute;
  top: -2px;
  right: -2px;
  line-height: 12px;
  padding: 0 3px;
  border-radius: 2em;
  background: var(--appearance-color-bg-primary);
  color: var(--color-on-surface);
}
.ThreadListItem-module__platformIcon {
  display: flex;
  font-size: 16px;
  width: 1em;
  height: 1em;
  position: absolute;
  right: -0.125em;
  bottom: 0;
  overflow: hidden;
}
.ThreadListItem-module__platformIcon .is-badge {
  border-radius: 50%;
}
.ThreadListItem-module__platformIcon .is-badge .brand-background {
  background: var(--color-secondary-container) !important;
}
.ThreadListItem-module__platformIcon .is-badge .brand-combined-icon {
  color: var(--palette-base-black);
}
@media (prefers-color-scheme: dark) {
  .ThreadListItem-module__platformIcon .is-badge .brand-combined-icon {
    color: var(--palette-base-white);
  }
}
.ThreadListItem-module__content {
  anchor-name: var(--content-anchor-name);
  margin-left: var(--dimension-100);
  align-self: stretch;
  width: 100%;
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.ThreadListItem-module__header {
  flex-shrink: 0;
  gap: 0.25rem;
  display: flex;
  align-items: center;
}
.ThreadListItem-module__header svg {
  font-size: 12px;
  flex-shrink: 0;
}
.ThreadListItem-module__title {
  font-weight: 600;
  font-size: var(--semantic-typo-size-body-md);
  line-height: var(--semantic-typo-line-height-body-md);
  letter-spacing: var(--semantic-typo-letter-spacing-body-md);
  line-height: var(--semantic-typo-line-height-body-sm);
  margin: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.ThreadListItem-module__show-unreads:not(.ThreadListItem-module__isUnread)
  .ThreadListItem-module__title {
  font-weight: 500;
}
.ThreadListItem-module__body {
  --max-line-count: 2;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
}
.ThreadListItem-module__previewWithMedia {
  display: flex;
  gap: var(--dimension-200);
  align-items: flex-start;
  min-width: 0;
}
.ThreadListItem-module__preview {
  font-weight: 400;
  font-size: var(--semantic-typo-size-body-sm);
  line-height: var(--semantic-typo-line-height-body-sm);
  letter-spacing: var(--semantic-typo-letter-spacing-body-sm);
  display: -webkit-box;
  height: calc(var(--max-line-count) * 1lh);
  line-clamp: var(--max-line-count);
  -webkit-line-clamp: var(--max-line-count);
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.ThreadListItem-module__previewText {
  opacity: 0.7;
}
.ThreadListItem-module__timestamp {
  font-weight: 400;
  font-size: var(--semantic-typo-size-label-sm);
  line-height: var(--semantic-typo-line-height-label-sm);
  letter-spacing: var(--semantic-typo-letter-spacing-label-sm);
  color: var(--color-on-surface);
  opacity: 0.7;
  margin-left: auto;
  padding-left: 0.5em;
  white-space: nowrap;
  display: flex;
  gap: 4px;
  align-items: center;
}
.ThreadListItem-module__actions {
  position: relative;
  margin-top: 2px;
  margin-left: auto;
  min-width: 18px;
  text-align: right;
  flex-shrink: 0;
  display: flex;
  justify-content: flex-end;
}
.ThreadListItem-module__checkboxMode .ThreadListItem-module__actions {
  display: none;
}
.ThreadListItem-module__proIndicators {
  display: flex;
  gap: 2px;
  flex-direction: row;
  align-items: center;
  justify-content: flex-end;
  width: 100%;
  height: 100%;
  transition:
    opacity ease-in-out,
    visibility ease-in-out,
    transform ease-in-out;
  transition-duration: var(--animation-timing);
}
.ThreadListItem-module__wrapper:hover
  .ThreadListItem-module__hoverActions:not(:empty)
  + .ThreadListItem-module__proIndicators {
  opacity: 0;
  transform: scale(0);
  visibility: hidden;
}
.ThreadListItem-module__unreadCount {
  display: flex;
  gap: 2px;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: var(--semantic-typo-size-label-xs);
  line-height: var(--semantic-typo-line-height-label-xs);
  letter-spacing: var(--semantic-typo-letter-spacing-label-xs);
  min-width: 1lh;
  height: 1lh;
  font-variant-numeric: tabular-nums;
  padding: 3px 4px;
  border-radius: 2em;
  background: var(--color-primary);
  color: var(--appearance-color-text-on-main);
}
.ThreadListItem-module__isMuted .ThreadListItem-module__unreadCount {
  background: rgba(var(--color-on-surface-rgb) / 0.3);
}
.ThreadListItem-module__unreadMention {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 1em;
  padding-right: 1px;
  color: var(--color-primary);
}
.ThreadListItem-module__hoverActions {
  position: absolute;
  top: -6px;
  right: -4px;
  opacity: 0;
  visibility: hidden;
}
.ThreadListItem-module__hoverActions button {
  padding: 6px;
  transform: scale(0.3);
}
.ThreadListItem-module__hoverActions,
.ThreadListItem-module__hoverActions button {
  transition:
    opacity ease-in-out,
    visibility ease-in-out,
    transform ease-in-out;
  transition-duration: var(--animation-timing);
}
.ThreadListItem-module__wrapper:hover .ThreadListItem-module__hoverActions {
  opacity: 1;
  visibility: visible;
}
.ThreadListItem-module__wrapper:hover
  .ThreadListItem-module__hoverActions
  button {
  transform: scale(1);
}
.TypingIndicator-module__wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
}
.TypingIndicator-module__dot {
  width: 0.25rem;
  height: 0.25rem;
  border-radius: 100%;
  background: currentColor;
  opacity: 0.2;
  animation: TypingIndicator-module__typingPulse 1s infinite;
}
.TypingIndicator-module__dot + .TypingIndicator-module__dot {
  margin-left: 2px;
}
.TypingIndicator-module__dot:nth-child(2) {
  animation-delay: 0.1s;
}
.TypingIndicator-module__dot:nth-child(3) {
  animation-delay: 0.2s;
}
@keyframes TypingIndicator-module__typingPulse {
  0% {
    opacity: 0.2;
  }
  15% {
    opacity: 0.4;
  }
  30% {
    opacity: 0.2;
  }
}
.Checkbox-module__root {
  display: inline-flex;
  align-items: center;
  position: relative;
}
.Checkbox-module__input {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: var(--checkbox-size-wrapper-size);
  height: var(--checkbox-size-wrapper-size);
  margin: 0;
  opacity: 0;
}
.Checkbox-module__box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  pointer-events: none;
  width: var(--checkbox-size-wrapper-size);
  height: var(--checkbox-size-wrapper-size);
  border: var(--checkbox-size-border-width) solid var(--checkbox-style-border);
  border-radius: var(--checkbox-size-radius);
  background: transparent;
  color: var(--checkbox-style-icon-selected);
}
.Checkbox-module__input:checked + .Checkbox-module__box {
  border-width: var(--checkbox-size-border-width-on);
  background: var(--checkbox-style-bg-selected);
}
.Checkbox-module__input:focus-visible + .Checkbox-module__box {
  outline: 2px solid var(--control-focus-ring, var(--app-focus-ring));
  outline-offset: 1px;
}
.Checkbox-module__input:disabled + .Checkbox-module__box {
  opacity: 0.5;
}
.UnreadThreads-module__bubbleAvatar {
  display: flex;
  border-radius: 100%;
  background-color: var(--color-backing-shade);
}
.UnreadThreads-module__view {
  flex: 1;
  min-width: var(--min-sidebar-width);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--semantic-colors-bg-primary);
  border-radius: var(--theme-radius-md);
}
.UnreadThreads-module__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--density-space-xl);
  padding: var(--density-space-3xl) var(--density-space-4xl);
}
.UnreadThreads-module__title,
.UnreadThreads-module__count {
  font-weight: var(--semantic-typo-style-strong);
  font-size: var(--chat-list-pinned-item-title-font-size);
  line-height: var(--chat-list-pinned-item-title-line-height);
  letter-spacing: var(--semantic-typo-letter-spacing-label-sm);
}
.UnreadThreads-module__title {
  margin: 0;
  color: var(--semantic-colors-text-primary);
}
.UnreadThreads-module__count {
  padding: 0 var(--density-space-lg);
  color: var(--semantic-colors-text-tertiary);
  font-variant-numeric: tabular-nums;
}
.UnreadThreads-module__empty {
  padding: 0 var(--density-space-4xl);
  color: var(--semantic-colors-text-secondary);
}
.UnreadThreads-module__noSelection {
  margin: auto;
  padding: var(--density-space-5xl);
  color: var(--semantic-colors-text-secondary);
  text-align: center;
}
.UnreadThreads-module__list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  padding: 0 var(--density-space-xl) var(--density-space-xl);
}
.UnreadThreads-module__pill {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  box-sizing: border-box;
  margin: 4px 0;
  padding: 6px 8px 6px 12px;
