.Toggle-module__root {
  display: inline-flex;
  align-items: center;
  position: relative;
}
.Toggle-module__input {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: var(--toggle-size-wrapper-width);
  height: var(--toggle-size-wrapper-height);
  margin: 0;
  opacity: 0;
}
.Toggle-module__input:disabled {
  pointer-events: none;
}
.Toggle-module__track {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  pointer-events: none;
  width: var(--toggle-size-wrapper-width);
  height: var(--toggle-size-wrapper-height);
  padding: var(--toggle-size-wrapper-padding-off);
  border-radius: var(--theme-radius-full);
  background: var(--toggle-style-bg-off);
  transition: background 0.15s ease;
}
.Toggle-module__knob {
  width: var(--toggle-size-knob-width-off);
  height: var(--toggle-size-knob-height-off);
  border-radius: var(--theme-radius-full);
  background: var(--toggle-style-knob-off);
  transition:
    translate 0.15s ease,
    background 0.15s ease;
}
.Toggle-module__border {
  position: absolute;
  inset: 0;
  border: var(--toggle-size-border-width-off) solid var(--toggle-style-border);
  border-radius: var(--theme-radius-full);
}
.Toggle-module__input:checked + .Toggle-module__track {
  padding: var(--toggle-size-wrapper-padding);
  background: var(--toggle-style-bg-on);
}
.Toggle-module__input:checked + .Toggle-module__track .Toggle-module__knob {
  width: var(--toggle-size-knob-width);
  height: var(--toggle-size-knob-height);
  background: var(--toggle-style-knob-on);
  translate: calc(
      var(--toggle-size-wrapper-width) - var(--toggle-size-knob-width) - 2 *
        var(--toggle-size-wrapper-padding)
    )
    0;
}
.Toggle-module__input:checked + .Toggle-module__track .Toggle-module__border {
  border-width: var(--toggle-size-border-width-on);
}
.Toggle-module__input:disabled + .Toggle-module__track {
  opacity: 0.5;
}
.Toggle-module__input:focus-visible + .Toggle-module__track {
  outline: 2px solid var(--control-focus-ring, var(--app-focus-ring));
  outline-offset: 1px;
}
