    box-shadow:
      var(--appearance-shadow-md-1-offset-x)
        var(--appearance-shadow-md-1-offset-y)
        var(--appearance-shadow-md-1-blur) var(--appearance-shadow-md-1-spread)
        var(--appearance-shadow-md-1-color),
      var(--appearance-shadow-md-2-offset-x)
