  --easing-spring-reverse: cubic-bezier(0.84, -0.63, 0.55, 0.9);
  --shadows-base-none: 0px 0px 0px rgba(0, 0, 0, 0);
  --shadows-base-sm: 0px 2px 4px rgba(0, 0, 0, 0.03);
  --shadows-base-xl: 0px 13px 20px rgba(0, 0, 0, 0.11);
  --shadows-background-elevated: var(--shadows-base-xl);
  --shadows-button-secondary: var(--shadows-base-sm);
  --shadows-button-secondary-active: var(--shadows-base-none);
  --shadows-button-secondary-disabled: var(--shadows-base-none);
}
@media (prefers-color-scheme: dark) {
  :root {
    --shadows-base-none: 0px 0px 0px rgba(0, 0, 0, 0);
    --shadows-base-sm: 0px 2px 4px rgba(0, 0, 0, 0.03);
    --shadows-base-xl: 0px 13px 20px rgba(0, 0, 0, 0.11);
    --shadows-background-elevated: var(--shadows-base-xl);
    --shadows-button-secondary: var(--shadows-base-none);
    --shadows-button-secondary-active: var(--shadows-base-none);
    --shadows-button-secondary-disabled: var(--shadows-base-none);
  }
}
:root {
  --shadows-interactive-focus:
    0px 0px 0px 1px rgba(var(--color-base-system-blue-110-rgb) / 0.3),
    0px 0px 0px 4px rgba(var(--color-base-system-blue-90-rgb) / 0.4);
  --shadows-menu:
    0 2px 8px 0 rgba(0, 0, 0, 0.09), 0 8px 24px 6px rgba(0, 0, 0, 0.13);
}
