html {
  font: var(--custom-font-size, 16px)/1.4 var(--font-family);
  color-scheme: light dark;
}
html,
body,
#root {
  height: 100%;
}
body {
  font-size: var(--semantic-typo-size-body-sm);
  font-weight: var(--font-weight-regular);
  color: var(--color-text-neutrals);
  user-select: none;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}
video,
audio {
  outline: none;
}
a {
  text-decoration: none;
  color: inherit;
}
:not(bdi *) {
  unicode-bidi: plaintext;
}
h3,
h4 {
  font-weight: var(--font-weight-regular);
}
pre {
  word-break: break-all;
  white-space: pre-wrap;
}
input,
textarea {
  outline: 0;
  border: 0;
  background: none;
  color: inherit;
  font-size: inherit;
  resize: none;
}
button {
  outline: 0;
  color: inherit;
}
button,
input,
textarea,
select {
