  }
  45% {
    transform: translate3d(4px, 1px, 0) rotate(0.25deg);
  }
  50% {
    transform: translate3d(-4px, -1px, 0) rotate(-0.2deg);
  }
  55% {
    transform: translate3d(3px, 1px, 0) rotate(0.15deg);
  }
  60% {
    transform: translate3d(-3px, -1px, 0) rotate(-0.15deg);
  }
  65% {
    transform: translate3d(2px, 1px, 0) rotate(0.1deg);
  }
  70% {
    transform: translate3d(-2px, 0, 0) rotate(-0.1deg);
  }
  78% {
    transform: translate3d(1px, 0, 0) rotate(0.05deg);
  }
  88% {
    transform: translate3d(-1px, 0, 0) rotate(-0.05deg);
  }
  to {
    transform: translateZ(0) rotate(0);
  }
